@startuml

class Airline {
  + ID : int
}

class Airport {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : time
  + ArrivalTime : time
}

class Aircraft {
  + Type : string
  + IsWorking : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class RoleRequirement {
  + Role : string
  + MinPilots : int
}

Airline "1" -- "0..*" Flight
Airline "1" -- "0..*" Aircraft
Airline "1" -- "0..*" Pilot
Flight "0..*" -- "1" Airport : departure
Flight "0..*" -- "1" Airport : arrival
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1" Pilot : co-pilot
Flight "0..*" -- "1" Aircraft
Aircraft "0..*" -- "1" Airline

@enduml

